<section class="section-heading"><div><h2>Take your design with you</h2><p>Appearance and content only. Packages contain no credentials, private grid settings or executable code.</p></div></section><div class="two-column"><section class="studio-panel"><h2>Export a complete design</h2><form method="post"><?php $hidden('package_export')?><label>Package name<input name="name" required maxlength="120" value="My website design"></label><label>Front-page layout<select name="pageId"><option value="">Themes and branding only</option><?php foreach($pages as $p):if(!isset($p['builder'])||$p['access']!=='public'||ag_sa_login_count($p['builder']['blocks'])!==1)continue;?><option value="<?=ag_h($p['id'])?>"><?=ag_h($p['title'])?></option><?php endforeach ?></select></label><?php $scopeFields(array_keys(ag_sd_scopes()))?><button>Export design ZIP</button></form></section><section class="studio-panel"><h2>Import a design package</h2><p>ZIP up to 32 MB; expanded content up to 24 MB. Import creates a private draft and never activates it.</p><form method="post" enctype="multipart/form-data"><?php $hidden('package_import')?><label>Design ZIP<input type="file" name="designPackage" accept=".zip,application/zip" required></label><button>Validate &amp; import as draft</button></form></section></div><div class="theme-grid"><?php foreach(ag_sd_import_list() as $design):?><article class="studio-panel"><?=ag_sd_visual_card(reset($design['themes']),$design['name'])?><span class="step">PRIVATE IMPORTED DRAFT</span><h3><?=ag_h($design['name'])?></h3><p class="package-meta">Version <?=intval($design['version'] ?? 1)?> · <?=intval($design['artworkCount'] ?? 0)?> artwork files · Imported package</p><p class="scope-chips"><?=ag_h(implode(' / ',array_keys($design['themes'])))?></p><form method="post"><?php $hidden('package_export')?><input type="hidden" name="designId" value="<?=ag_h($design['id'])?>"><input type="hidden" name="name" value="<?=ag_h($design['name'])?>"><?php foreach(array_keys($design['themes']) as $scope):?><input type="hidden" name="scopes[]" value="<?=ag_h($scope)?>"><?php endforeach ?><button class="quiet">Export this package</button></form><button type="button" class="secondary preview-design" data-url="/Other/site-front-preview.php?design=<?=ag_h($design['id'])?>">Preview</button><?php if($design['pageId']):?><a class="button secondary" href="/Other/admin-page-designer.php?id=<?=ag_h($design['pageId'])?>">Edit page</a><?php endif ?><?php foreach(array_keys($design['themes']) as $area):?><button type="button" class="secondary preview-design" data-url="/Other/site-theme-preview.php?design=<?=ag_h($design['id'])?>&amp;scope=<?=ag_h($area)?>">Preview <?=ag_h(ag_sd_scopes()[$area])?></button><?php endforeach ?><form method="post"><?php $hidden('package_apply')?><input type="hidden" name="designId" value="<?=ag_h($design['id'])?>"><input type="hidden" name="pageRevision" value="<?=ag_h($design['pageId']?ag_pd_editor_revision($design['pageId']):'')?>"><?php $scopeFields(array_keys($design['themes']))?><label class="check"><input type="checkbox" name="applyBranding" value="1"> Apply this package’s shared branding</label><label class="check"><input type="checkbox" name="reviewed" value="1" required> I previewed and reviewed this design.</label><div class="accessibility"><?php foreach($design['themes'] as $theme)foreach(ag_sd_accessibility($theme,$design['pageId']?ag_pd_edit_page($design['pageId']):null) as $warning):?><p><?=ag_h($warning)?></p><?php endforeach ?></div><button>Apply reviewed design</button><p>Public Website selection activates the included native login page. Unchecked areas stay unchanged.</p></form></article><?php endforeach ?></div>
